#[derive(Debug)]
struct ScriptedCheckpointModel {
    responses: Vec<String>,
    response_index: usize,
    calls: Vec<Vec<Message>>,
    reuse: PrefixReuse,
}

#[derive(Debug, Clone)]
struct DenseCacheState {
    key_values: Option<Rc<Vec<i64>>>,
    offset: i64,
}

#[derive(Debug)]
struct DenseCache {
    object_id: u64,
    state: RefCell<DenseCacheState>,
}

impl DenseCache {
    fn empty() -> Self {
        Self {
            object_id: NEXT_CACHE_ID.fetch_add(1, Ordering::Relaxed),
            state: RefCell::new(DenseCacheState {
                key_values: None,
                offset: 0,
            }),
        }
    }

    fn key_values_id(&self) -> Option<usize> {
        self.state
            .borrow()
            .key_values
            .as_ref()
            .map(|values| Rc::as_ptr(values) as usize)
    }

    fn update(&self, tokens: &[i64], layer: i64) {
        let mut state = self.state.borrow_mut();
        let mut values = state
            .key_values
            .as_ref()
            .map_or_else(Vec::new, |values| (**values).clone());
        values.extend(tokens.iter().map(|token| token + layer));
        state.key_values = Some(Rc::new(values));
        state.offset += tokens.len() as i64;
    }
}

impl GenerationCache for DenseCache {
    fn release(&mut self) {
        self.state.get_mut().key_values = None;
    }

    fn as_any(&self) -> &dyn std::any::Any {
        self
    }

    fn offset(&self) -> i64 {
        self.state.borrow().offset
    }

    fn fork_box(&self) -> Result<Box<dyn GenerationCache>, AgentError> {
        Ok(Box::new(Self {
            object_id: NEXT_CACHE_ID.fetch_add(1, Ordering::Relaxed),
            state: RefCell::new(self.state.borrow().clone()),
        }))
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct DenseCall {
    offset: i64,
    size: usize,
    logits_to_keep: Option<usize>,
    cache_objects: Vec<u64>,
    before: Vec<Option<usize>>,
    after: Vec<Option<usize>>,
}

#[derive(Debug, Default)]
struct DenseEosModel {
    calls: Vec<DenseCall>,
}

impl GenerationModel for DenseEosModel {
    fn forward(
        &mut self,
        tokens: &[i64],
        offset: i64,
        caches: &mut [Box<dyn GenerationCache>],
        logits_to_keep: Option<usize>,
    ) -> Result<Vec<f32>, AgentError> {
        let cache_objects = caches
            .iter()
            .map(|cache| {
                cache
                    .as_any()
                    .downcast_ref::<DenseCache>()
                    .expect("dense cache")
                    .object_id
            })
            .collect::<Vec<_>>();
        let before = caches
            .iter()
            .map(|cache| {
                cache
                    .as_any()
                    .downcast_ref::<DenseCache>()
                    .expect("dense cache")
                    .key_values_id()
            })
            .collect::<Vec<_>>();
        for (layer, cache) in caches.iter().enumerate() {
            cache
                .as_any()
                .downcast_ref::<DenseCache>()
                .expect("dense cache")
                .update(tokens, layer as i64);
        }
        let after = caches
            .iter()
            .map(|cache| {
                cache
                    .as_any()
                    .downcast_ref::<DenseCache>()
                    .expect("dense cache")
                    .key_values_id()
            })
            .collect();
        self.calls.push(DenseCall {
            offset,
            size: tokens.len(),
            logits_to_keep,
            cache_objects,
            before,
            after,
        });

        // EOS (token zero) is the unique greedy maximum.
        let mut logits = vec![0.0; 128];
        logits[0] = 1.0;
        Ok(logits)
    }

    fn new_caches(&self) -> Result<Vec<Box<dyn GenerationCache>>, AgentError> {
        Ok(vec![
            Box::new(DenseCache::empty()),
            Box::new(DenseCache::empty()),
        ])
    }
}

#[derive(Debug, Default)]
struct CharacterTokenizer;

impl GenerationTokenizer for CharacterTokenizer {
    fn eos_token_id(&self) -> i64 {
        0
    }

    fn apply_chat_template(
        &mut self,
        messages: &[Message],
        tokenize: bool,
        add_generation_prompt: bool,
        enable_thinking: bool,
    ) -> Result<String, AgentError> {
        assert!(!tokenize);
        assert!(!enable_thinking);
        let mut rendered = String::new();
        for message in messages {
            rendered.push('<');
            rendered.push_str(&message["role"]);
            rendered.push('>');
            rendered.push_str(&message["content"]);
            rendered.push('\n');
        }
        if add_generation_prompt {
            rendered.push_str("<assistant>");
        }
        Ok(rendered)
    }

    fn encode(&mut self, prompt: &str, add_special_tokens: bool) -> Result<Vec<i64>, AgentError> {
        assert!(!add_special_tokens);
        Ok(prompt.chars().map(|character| character as i64).collect())
    }

    fn decode(&mut self, tokens: &[i64]) -> Result<String, AgentError> {
        tokens
            .iter()
            .map(|token| {
                char::from_u32(*token as u32)
                    .ok_or_else(|| AgentError("invalid character token".to_owned()))
            })
            .collect()
    }
}

fn message(role: &str, content: &str) -> Message {
    Message::from([
        ("role".to_owned(), role.to_owned()),
        ("content".to_owned(), content.to_owned()),
    ])
}

impl ScriptedCheckpointModel {
    fn new(responses: impl IntoIterator<Item = impl Into<String>>) -> Self {
        Self {
            responses: responses.into_iter().map(Into::into).collect(),
            response_index: 0,
            calls: Vec::new(),
            reuse: PrefixReuse {
                reused_tokens: 0,
                layer_offsets: vec![],
                avoided_prefill_tokens: 0,
            },
        }
    }

    fn tokens(messages: &[Message]) -> Vec<i64> {
        messages
            .iter()
            .map(|message| message["content"].chars().count() as i64)
            .collect()
    }
}

impl Generate for ScriptedCheckpointModel {
    fn generate(&mut self, messages: &[Message]) -> Result<String, AgentError> {
        self.calls.push(messages.to_vec());
        let response = self
            .responses
            .get(self.response_index)
            .cloned()
            .ok_or_else(|| AgentError("scripted model ran out of responses".to_owned()))?;
        self.response_index += 1;
        Ok(response)
    }

    fn save_checkpoint(&mut self, messages: &[Message]) -> Result<ModelCheckpoint, AgentError> {
        let tokens = Self::tokens(messages);
        ModelCheckpoint::new(
            messages.len() as i64,
            self.response_index as i64,
            tokens.clone(),
            vec![tokens.len() as i64, tokens.len() as i64],
        )
    }

    fn restore_checkpoint(&mut self, checkpoint: &ModelCheckpoint) -> Result<(), AgentError> {
        self.response_index = checkpoint.response_index as usize;
        self.reuse = PrefixReuse {
            reused_tokens: checkpoint.cached_token_ids.len() as i64,
            layer_offsets: checkpoint.layer_offsets.clone(),
            avoided_prefill_tokens: checkpoint.cached_token_ids.len() as i64,
        };
        Ok(())
    }

    fn prefix_reuse(&self) -> Option<(i64, Vec<i64>, i64)> {
        Some((
            self.reuse.reused_tokens,
            self.reuse.layer_offsets.clone(),
            self.reuse.avoided_prefill_tokens,
        ))
    }
}

#[test]
fn test_task_1_structured_denial_requires_and_exposes_one_operator_reason() {
    let temp = TestDir::new("day8-structured-denial");
    fs::write(temp.path().join("app.py"), b"answer = 2\n").expect("seed app.py");
    let receipts =
        ReceiptStore::new(Some(temp.path().join("receipts.jsonl"))).expect("create receipt store");
    let mut workspace = Workspace::new(
        policy(temp.path(), true, vec![]),
        Some(Box::new(|_action| {
            ConfirmResult::Decision(
                ApprovalDecision::new(false, "keep the requested answer at 2".to_owned())
                    .expect("valid structured denial"),
            )
        })),
        receipts,
    );
    workspace.read_file("app.py").expect("observe before edit");

    let result = workspace.execute(
        &action(
            "edit_file",
            json!({"path": "app.py", "old": "2", "new": "3"}),
        ),
        None,
    );
    // .expect("denial remains model-visible");

    assert_eq!(
        result,
        "error: operator denied the tool action: keep the requested answer at 2"
    );
    assert_eq!(result.matches("keep the requested answer at 2").count(), 1);
    assert_eq!(
        fs::read_to_string(temp.path().join("app.py")).expect("read app.py"),
        "answer = 2\n"
    );
    assert!(workspace.receipt_store.get("call-1").is_none());
    let error = ApprovalDecision::new(false, "  ".to_owned()).unwrap_err();
    assert!(error.to_string().contains("nonblank operator reason"));
}

